        inds=[r for r in range(h) if grid[r][c]]
        if inds and len(inds)>=2 and all(grid[r][c]==grid[inds[0]][c] for r in inds):
            # vertical marker continuing below/above the horizontal pattern
            vcols.append((c,grid[inds[0]][c],min(inds),max(inds)))
    for c,mark,lo,hi in vcols:
        # Preserve the marker's original unpatterned tail; extend only across
        # the horizontal stripe region, with each stripe's local color.
        for r in range(h):
            if r<=hi and r>=0:
                # determine nearest horizontal stripe row, using its color at c
                candidates=[sr for sr in stripe_rows if sr>=r]
                if candidates:
