 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    stripes=[]
    for r,row in enumerate(grid):
        nz=[c for c,v in enumerate(row) if v]
        if len(nz)>=3 and max(nz)-min(nz)>=4:
            stripes.append(r)
            # close one-cell breaks in the horizontal stripe
            for c in range(min(nz),max(nz)+1):
                if row[c]==0:
                    left=next((row[x] for x in range(c-1,-1,-1) if row[x]),0)
                    right=next((row[x] for x in range(c+1,w) if row[x]),0)
                    if left and right and left==right: g[r][c]=left
    # A stripe's gap-columns project upward, stopping after the previous stripe.
    for i,r in enumerate(stripes):
        prev=stripes[i-1] if i else -1
        row=grid[r]
        nz=[c for c,v in enumerate(row) if v]
        for c in range(min(nz),max(nz)+1):
            if row[c]==0:
                color=next((row[x] for x in range(c-1,-1,-1) if row[x]),0)
                for rr in range(max(0,prev+1),r):
                    if g[rr][c]==0: g[rr][c]=color
    return g
